import React, { useEffect, useState, useRef } from "react";
import SockJS from "sockjs-client";
import { Client } from "@stomp/stompjs";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const API_BASE = process.env.REACT_APP_API_BASE_URL || "http://localhost:8080";

export default function LudoBoard() {
  const [boardState, setBoardState] = useState(null);
  const [currentPlayer, setCurrentPlayer] = useState(0);
  const [gameOver, setGameOver] = useState(false);
  // playerProfiles হিসেবে দুই জন প্লেয়ারের প্রোফাইল রাখা হচ্ছে
  // structure: { player1: {...}, player2: {...} }
  const [playerProfiles, setPlayerProfiles] = useState({ player1: {}, player2: {} });
  const [diceValue, setDiceValue] = useState(null);
  const [diceOwner, setDiceOwner] = useState(null);
  const [diceHistory, setDiceHistory] = useState({ 1: [], 2: [] });

  const stompClientRef = useRef(null);
  const navigate = useNavigate();

  const token = localStorage.getItem("authToken");
  const sessionId = localStorage.getItem("currentSessionId");
  const playerGameId = localStorage.getItem("currentGameId");

  // Helper to get avatar URL
  const renderAvatar = (profile) => {
    if (profile?.avatarUrl) return `${API_BASE}${profile.avatarUrl}`;
    if (profile?.displayName)
      return `https://ui-avatars.com/api/?name=${encodeURIComponent(profile.displayName)}&background=0D8ABC&color=fff`;
    return "/default-avatar.png";
  };

  // Fetch user profile by gameId
  const fetchProfileById = async (id) => {
    if (!id) return null;
    try {
      const res = await axios.get(`${API_BASE}/api/user/profile/${id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      return res.data;
    } catch {
      return null;
    }
  };

  // WebSocket connect and subscribe
  useEffect(() => {
    if (!token || !sessionId) return;

    const socket = new SockJS(`${API_BASE}/ludo-ws?token=${encodeURIComponent(token)}`);
    const stompClient = new Client({
      webSocketFactory: () => socket,
      reconnectDelay: 5000,
      onConnect: () => {
        stompClient.subscribe(`/topic/game/${sessionId}`, async (msg) => {
          try {
            const state = JSON.parse(msg.body);
            setBoardState(state.playerTokens || []);
            setCurrentPlayer(state.currentPlayer ?? 0);
            setGameOver(state.gameOver || false);

            // State থেকে player IDs নাও
            if (state.players && state.players.length === 2) {
              const [p1Id, p2Id] = state.players;

              // playerProfiles আপডেট করার আগে চেক করো যদি আগের সেট করা না হয় বা আইডি বদলায়
              const prevProfiles = playerProfiles;
              if (
                prevProfiles.player1.gameId !== p1Id ||
                prevProfiles.player2.gameId !== p2Id
              ) {
                // player1 এবং player2 এর প্রোফাইল নিয়ে আসো
                const p1Profile = await fetchProfileById(p1Id);
                const p2Profile = await fetchProfileById(p2Id);

                setPlayerProfiles({ player1: p1Profile || {}, player2: p2Profile || {} });
              }
            }

            // Dice state আপডেট করো
            if (state.lastDiceValue !== undefined && state.currentPlayer !== undefined) {
              setDiceValue(state.lastDiceValue);
              setDiceOwner(state.currentPlayer);
              setDiceHistory((prev) => ({
                ...prev,
                [state.currentPlayer]: [...(prev[state.currentPlayer] || []), state.lastDiceValue],
              }));
            }
          } catch (err) {
            console.error("Error parsing game state:", err);
          }
        });
      },
    });

    stompClient.activate();
    stompClientRef.current = stompClient;
    return () => stompClient.deactivate();
  }, [sessionId, token]); // sessionId আর token পরিবর্তন হলে আবার কানেক্ট করবে

  const rollDice = () => {
    if (!sessionId) return alert("Game session not found.");
    axios
      .post(`${API_BASE}/api/game/roll/${sessionId}`, {}, { headers: { Authorization: `Bearer ${token}` } })
      .catch((err) => alert(err.response?.data || "Error rolling dice"));
  };

  const sendMove = (tokenIndex) => {
    if (!diceValue) {
      alert("Please roll the dice first!");
      return;
    }
    stompClientRef.current?.publish({
      destination: "/app/game/move",
      body: JSON.stringify({
        gameId: sessionId,
        playerId: currentPlayer,
        tokenIndex,
        diceValue,
      }),
    });
    setDiceValue(null);
    setDiceOwner(null);
  };

  const cancelGame = () => {
    if (!window.confirm("Are you sure you want to cancel the game?")) return;
    axios
      .post(`${API_BASE}/api/game/leave`, { gameId: sessionId }, { headers: { Authorization: `Bearer ${token}` } })
      .then(() => {
        localStorage.removeItem("currentSessionId");
        localStorage.removeItem("currentGameId");
        navigate("/");
      })
      .catch((err) => alert("Error cancelling game: " + (err.response?.data || err.message)));
  };

  if (gameOver) {
    return (
      <div className="flex flex-col items-center justify-center h-screen bg-gray-900 text-white">
        <h2 className="text-3xl font-bold mb-4">🎉 Game Over 🎉</h2>
        <button
          className="px-6 py-3 bg-primary text-white rounded-lg hover:bg-indigo-600"
          onClick={() => navigate("/")}
        >
          Back to Home
        </button>
      </div>
    );
  }

  return (
    <div className="p-4 min-h-screen flex flex-col bg-gradient-to-br from-indigo-900 via-purple-800 to-indigo-900">
      <style>{`
        @keyframes pulseGlow {
          0%, 100% { transform: scale(1); box-shadow: 0 0 15px gold; }
          50% { transform: scale(1.05); box-shadow: 0 0 30px gold; }
        }
        .avatar-anim { animation: pulseGlow 1.2s infinite ease-in-out; border: 4px solid gold; }
      `}</style>

      {/* Player 2 (opponent) */}
      <div className="flex flex-col items-center mb-6">
        <img
          src={renderAvatar(playerProfiles.player2)}
          alt="player2-avatar"
          className="w-24 h-24 rounded-full avatar-anim"
        />
        <span className="mt-2 text-xl font-bold text-white">
          {playerProfiles.player2?.displayName || "Opponent"}
        </span>
        {diceOwner === 2 && diceValue && (
          <span className="mt-1 text-xl font-bold text-yellow-300">🎲 {diceValue}</span>
        )}
      </div>

      {/* Board */}
      <div className="flex-grow bg-white rounded-lg shadow-lg p-4 mb-6">
        {boardState ? (
          <div className="grid grid-cols-2 gap-6">
            {boardState.map((tokens, playerIdx) => {
              const playerNumber = playerIdx + 1;
              const profile = playerNumber === 1 ? playerProfiles.player1 : playerProfiles.player2;
              return (
                <div
                  key={playerIdx}
                  className={`p-4 rounded-lg border-2 ${
                    currentPlayer === playerNumber ? "border-yellow-500" : "border-gray-300"
                  }`}
                >
                  <h4
                    className={`text-lg font-bold mb-4 ${
                      currentPlayer === playerNumber ? "text-yellow-500" : "text-gray-600"
                    }`}
                  >
                    {profile?.displayName || `Player ${playerNumber}`}
                  </h4>
                  <div className="flex flex-wrap gap-3">
                    {tokens.map((pos, tokenIdx) => (
                      <button
                        key={tokenIdx}
                        onClick={() => sendMove(tokenIdx)}
                        disabled={currentPlayer !== playerNumber}
                        className={`px-3 py-2 rounded-lg border ${
                          currentPlayer === playerNumber
                            ? "bg-yellow-400 text-black hover:bg-yellow-500"
                            : "bg-gray-200 text-gray-600 cursor-not-allowed"
                        }`}
                      >
                        Token {tokenIdx + 1} ({pos})
                      </button>
                    ))}
                  </div>
                  <div className="mt-4 text-sm text-gray-500">
                    Rolls: {diceHistory[playerNumber]?.join(", ") || "No rolls yet"}
                  </div>
                </div>
              );
            })}
          </div>
        ) : (
          <p className="text-center text-gray-300">Waiting for game to start...</p>
        )}
      </div>

      {/* Player 1 (self) */}
      <div className="flex flex-col items-center mt-4">
        <img
          src={renderAvatar(playerProfiles.player1)}
          alt="player1-avatar"
          className="w-24 h-24 rounded-full avatar-anim"
        />
        <span className="mt-2 text-xl font-bold text-white">
          {playerProfiles.player1?.displayName || "You"}
        </span>
        {diceOwner === 1 && diceValue && (
          <span className="mt-1 text-xl font-bold text-yellow-300">🎲 {diceValue}</span>
        )}
      </div>

      {/* Controls */}
      <div className="flex items-center gap-4 mt-4">
        <button
          onClick={rollDice}
          className="px-4 py-2 rounded-lg text-white bg-yellow-500 hover:bg-yellow-600"
        >
          🎲 Roll Dice
        </button>
        <button
          onClick={cancelGame}
          className="px-4 py-2 rounded-lg bg-red-600 text-white hover:bg-red-700 ml-4"
        >
          🔙 Back
        </button>
      </div>
    </div>
  );
}
